// Wallet IDs for the ethers-based panels.
//
// Player entry points take a uint32 account ID first, and usually 0 means "the caller"
// (DegenerusGame._resolveAccountId). A write the connected wallet makes for itself therefore sends
// 0 and needs no lookup at all. Acting for another account (operator mode, `getActingAddress()`
// returning the viewed wallet) sends that account's ID, read once from Game `walletIdOf_g3120`.
// Views and storage keyed by ID use readWalletId(). depositAfkingFunding also needs a nonzero
// recipient ID, including self.
//
// The chain-route equivalent (snapshot-based, cached per snapshot) is app/chain/wallets.js.
import { ethers } from 'ethers';
import { CONTRACTS } from './chain-config.js';
import { get } from './store.js';
import { permissionlessReadProvider } from './read-provider.js';

export const WALLET_ID_ABI = Object.freeze([
  'function walletIdOf_g3120(address player) view returns (uint32)',
]);

const cache = new Map(); // Latest observation for synchronous receipt fallback only; reads always refresh.
const testIds = new Map();
let _providerOverride = null;

const lower = value => String(value ?? '').toLowerCase();
const isAddress = value => /^0x[0-9a-f]{40}$/i.test(String(value ?? ''));

/** True when `target` is the connected wallet (the account a 0 ID resolves to). */
export function isConnectedWallet(target) {
  const connected = get('connected.address');
  return !!connected && !!target && lower(connected) === lower(target);
}

/** Synchronous cache read; undefined when unknown. */
export function cachedWalletId(address) {
  return cache.get(`${lower(CONTRACTS.GAME)}:${lower(address)}`);
}

/** Tests: seed or clear the cache, or inject a provider. */
export function _setWalletIdForTests(address, id) {
  const key = `${lower(CONTRACTS.GAME)}:${lower(address)}`;
  if (id == null) { cache.delete(key); testIds.delete(key); }
  else { cache.set(key, Number(id)); testIds.set(key, Number(id)); }
}
export function _resetWalletIdsForTests() { cache.clear(); testIds.clear(); _providerOverride = null; }
export function _setWalletIdProviderForTests(provider) { _providerOverride = provider; }

/**
 * The wallet ID of `address` (number), 0 when it has not registered yet, or null when the read
 * failed.
 */
export async function readWalletId(address, { provider, blockTag } = {}) {
  if (!isAddress(address)) return null;
  const hit = testIds.get(`${lower(CONTRACTS.GAME)}:${lower(address)}`);
  if (hit) return hit;
  const reader = provider ?? _providerOverride ?? permissionlessReadProvider(null);
  if (!reader || !CONTRACTS.GAME) return null;
  try {
    const id = Number(await new ethers.Contract(CONTRACTS.GAME, WALLET_ID_ABI, reader).walletIdOf_g3120(address, ...(blockTag == null ? [] : [{ blockTag }])));
    cache.set(`${lower(CONTRACTS.GAME)}:${lower(address)}`, id);
    return id;
  } catch (_e) {
    return null;
  }
}

/**
 * The first argument of a player transaction for `target`: 0 for the connected wallet and the
 * target's wallet ID otherwise. Throws when acting for a wallet that has no ID (nothing can be
 * done for it yet).
 */
export async function accountArg(target, options = {}) {
  if (!target || isConnectedWallet(target)) return 0;
  const id = await readWalletId(target, options);
  if (id == null) throw new Error('Could not read that wallet\'s game account. Try again.');
  if (!id) throw new Error('That wallet has no game account yet.');
  return id;
}

/** Synchronous accountArg for paths that cannot await: 0 for self, the cached ID, else throws. */
export function accountArgSync(target) {
  if (!target || isConnectedWallet(target)) return 0;
  const id = cachedWalletId(target);
  if (!id) throw new Error('That wallet\'s game account is not loaded yet. Try again.');
  return id;
}
